-- Go Getter 3, юнит 1 по рабочей тетради: домашки 1–2 (черновики)
update classroom_lessons set sort_order = 10 where id = '87f1ce1e-8300-43d2-82b0-594ff8099a0f';

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '96161506-701b-4074-9115-ee113b71a739' and title = 'Homework 1';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('96161506-701b-4074-9115-ee113b71a739', 'Homework 1', 0, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 0, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 1 · Life at home</h2><p>Сегодня — дела по дому: как они называются по-английски и как про них рассказать.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'flashcards', $blk${"title": "Повторяем слова урока. Нажми на карточку — услышишь слово и увидишь перевод", "cards": [{"text": "make the bed", "translation": "застилать кровать", "audio": "", "audio_tts": {"text": "make the bed.", "voice": "en_GB-alba"}}, {"text": "load the dishwasher", "translation": "загружать посудомойку", "audio": "", "audio_tts": {"text": "load the dishwasher.", "voice": "en_GB-alba"}}, {"text": "empty the dishwasher", "translation": "разгружать посудомойку", "audio": "", "audio_tts": {"text": "empty the dishwasher.", "voice": "en_GB-alba"}}, {"text": "wash the dishes", "translation": "мыть посуду", "audio": "", "audio_tts": {"text": "wash the dishes.", "voice": "en_GB-alba"}}, {"text": "vacuum the living room", "translation": "пылесосить гостиную", "audio": "", "audio_tts": {"text": "vacuum the living room.", "voice": "en_GB-alba"}}, {"text": "take out the rubbish", "translation": "выносить мусор", "audio": "", "audio_tts": {"text": "take out the rubbish.", "voice": "en_GB-alba"}}, {"text": "water the plants", "translation": "поливать растения", "audio": "", "audio_tts": {"text": "water the plants.", "voice": "en_GB-alba"}}, {"text": "feed my pet", "translation": "кормить питомца", "audio": "", "audio_tts": {"text": "feed my pet.", "voice": "en_GB-alba"}}, {"text": "set the table", "translation": "накрывать на стол", "audio": "", "audio_tts": {"text": "set the table.", "voice": "en_GB-alba"}}, {"text": "clear the table", "translation": "убирать со стола", "audio": "", "audio_tts": {"text": "clear the table.", "voice": "en_GB-alba"}}, {"text": "iron my T-shirt", "translation": "гладить футболку", "audio": "", "audio_tts": {"text": "iron my T-shirt.", "voice": "en_GB-alba"}}, {"text": "put away my clothes", "translation": "убирать одежду", "audio": "", "audio_tts": {"text": "put away my clothes.", "voice": "en_GB-alba"}}, {"text": "load the washing machine", "translation": "загружать стиральную машину", "audio": "", "audio_tts": {"text": "load the washing machine.", "voice": "en_GB-alba"}}, {"text": "tidy my room", "translation": "убирать комнату", "audio": "", "audio_tts": {"text": "tidy my room.", "voice": "en_GB-alba"}}, {"text": "cook lunch", "translation": "готовить обед", "audio": "", "audio_tts": {"text": "cook lunch.", "voice": "en_GB-alba"}}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Посмотри на картинку и выбери правильный вариант", "questions": [{"q": "", "image": "https://classroom.wowteach.ru/media/gg3/u1/chore_dishwasher.webp", "type": "single", "correct": [1], "options": [{"text": "wash the dishes"}, {"text": "empty the dishwasher"}, {"text": "load the dishwasher"}]}, {"q": "", "image": "https://classroom.wowteach.ru/media/gg3/u1/chore_vacuum.webp", "type": "single", "correct": [2], "options": [{"text": "make the bed"}, {"text": "take out the rubbish"}, {"text": "vacuum the living room"}]}, {"q": "", "image": "https://classroom.wowteach.ru/media/gg3/u1/chore_feed_pet.webp", "type": "single", "correct": [0], "options": [{"text": "feed my pet"}, {"text": "water the plants"}, {"text": "clear the table"}]}, {"q": "", "image": "https://classroom.wowteach.ru/media/gg3/u1/chore_set_table.webp", "type": "single", "correct": [1], "options": [{"text": "cook lunch"}, {"text": "set the table"}, {"text": "iron my T-shirt"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения", "pairs": [{"left": "Can you iron", "right": "my T-shirt, please?"}, {"left": "Anna always puts", "right": "away her clothes."}, {"left": "Dad often clears the", "right": "table after dinner."}, {"left": "We make our", "right": "beds before we go to school."}, {"left": "Please take", "right": "out the rubbish."}, {"left": "Grandpa waters", "right": "our plants on hot days."}, {"left": "Tina usually loads", "right": "the washing machine."}, {"left": "Mum cooks", "right": "lunch at the weekend."}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'sort', $blk${"title": "Распредели глаголы: что с чем делают", "groups": [{"name": "the dishwasher", "items": [{"text": "load"}, {"text": "empty"}]}, {"name": "my room", "items": [{"text": "vacuum"}, {"text": "tidy"}]}, {"name": "my clothes", "items": [{"text": "iron"}, {"text": "put away"}]}, {"name": "the table", "items": [{"text": "set"}, {"text": "clear"}]}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай блог Кэти и перетащи слова в пропуски", "mode": "drag", "text": "Hi! Today I want to tell you about my new friend, Charlie.\nCharlie helps his parents every day. He makes his bed after he gets up. Before breakfast he empties the __dishwasher__ and puts the plates and glasses in the kitchen cupboard.\nWhen it's hot, he waters the __plants__ in the garden. Then he goes to school.\nHe gets home from school at two o'clock and he feeds the __cat__ because it's her lunch time.\nHis favourite chore is cooking __dinner__ with his dad because it's fun."}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "Расскажи о своих делах по дому 🎤", "needs_review": true, "html": "<p>Назови три дела, которые ты делаешь дома, и скажи, какое тебе нравится больше всего.</p><p><i>Например: I take out the rubbish every evening. I like cooking with my mum.</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_star.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! Теперь ты можешь рассказать, кто что делает дома.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '96161506-701b-4074-9115-ee113b71a739' and title = 'Homework 2';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('96161506-701b-4074-9115-ee113b71a739', 'Homework 2', 1, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 1, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_laptop.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 1 · Life at home</h2><p>Грамматика: Present Continuous — что происходит прямо сейчас — и глаголы, которые в нём не используются.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Посмотри на картинку и выбери: верно или неверно", "questions": [{"q": "Peter is listening to music.", "image": "https://classroom.wowteach.ru/media/gg3/u1/fam_bed.webp", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "Dad is washing the dishes.", "image": "https://classroom.wowteach.ru/media/gg3/u1/fam_dishes.webp", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "Peter's brothers are feeding the cat.", "image": "https://classroom.wowteach.ru/media/gg3/u1/fam_cat.webp", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "Peter's sister is doing her homework.", "image": "https://classroom.wowteach.ru/media/gg3/u1/fam_phone.webp", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Расставь слова по порядку — получится вопрос мамы", "items": [{"words": ["Is", "your", "sister", "vacuuming", "her", "room?"], "sentence": "Is your sister vacuuming her room?"}, {"words": ["Are", "your", "brothers", "sleeping?"], "sentence": "Are your brothers sleeping?"}, {"words": ["Is", "Dad", "making", "breakfast?"], "sentence": "Is Dad making breakfast?"}, {"words": ["Are", "you", "making", "your", "bed,", "Peter?"], "sentence": "Are you making your bed, Peter?"}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери правильный вариант", "questions": [{"q": "The dog ___ food. He’s hungry.", "type": "single", "correct": [1], "options": [{"text": "is needing"}, {"text": "needs"}]}, {"q": "I ___ the answers.", "type": "single", "correct": [0], "options": [{"text": "don't know"}, {"text": "am not knowing"}]}, {"q": "___ watching films on TV?", "type": "single", "correct": [1], "options": [{"text": "Are you liking"}, {"text": "Do you like"}]}, {"q": "Where’s Dad? He ___ lunch.", "type": "single", "correct": [0], "options": [{"text": "is cooking"}, {"text": "cooks"}]}, {"q": "Mum ___ the beds. Let’s help her.", "type": "single", "correct": [1], "options": [{"text": "makes"}, {"text": "is making"}]}, {"q": "___ his new phone?", "type": "single", "correct": [1], "options": [{"text": "Is Dave loving"}, {"text": "Does Dave love"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор и выбери правильную форму глагола", "mode": "choice", "text": "Emma: Hi, Harry. What are you doing?\nHarry: I __am setting__ the table for dinner. Why __are you asking__?\nEmma: I __need__ some help with tidying my room. I __don't like__ doing it on my own. Please!\nHarry: I've got my own chores, thanks!\nEmma: What about George? __Is he doing__ any work now? Can he help me?\nHarry: George __hates__ chores too! He __doesn't like__ tidying or vacuuming.", "choices": [["set", "am set"], ["do you ask", "you are asking"], ["am needing", "needs"], ["am not liking", "doesn’t like"], ["Does he doing", "Is he do"], ["is hating", "hate"], ["isn't liking", "don't like"]]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "Допиши разговор с другом ✍️", "needs_review": true, "html": "<p>Представь, что сейчас субботнее утро. Ты звонишь другу. Допиши разговор — по одному предложению в каждой строке.</p><p><b>You:</b> Hi! What are you doing?<br><b>Your friend:</b> I … (tidy / my bedroom).<br><b>You:</b> Poor you! I … (hate) tidying my room.<br><b>Your friend:</b> And what about you?<br><b>You:</b> Well, I … (vacuum / my room) …<br><b>Your friend:</b> I … (not like) vacuuming. It’s boring!</p><p><i>Например: I’m washing the dishes. I don’t like doing the dishes.</i></p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_thumb.webp\" alt=\"\" style=\"height:200px\"></p><p>Готово! Теперь ты знаешь, какие глаголы не ставят в Present Continuous.</p>"}$blk$::jsonb, 6);
end $$;
